class SmartCaptcha{constructor(key){this.key=key}addSmartCaptcha(form){if(window.smartCaptcha){const container=form.form.querySelector(".smart-captcha-container");return window.smartCaptcha.render(container,{sitekey:this.key,hl:"ru"})}return false}setSmartCaptcha(widgetId){window.smartCaptcha.execute(widgetId)}}